```js
// task-2bb0bc24 live proof: the FIXED production ledger + decider over a COPY of the UnAI store.
import { DatabaseSync } from "node:sqlite";
import { pathToFileURL } from "node:url";

const SCRATCH = process.argv[2];
const COPY = `${SCRATCH}/store.sqlite`;
if (!/[\\/]temp[\\/]moe-task-2bb0bc24-/iu.test(COPY)) throw new Error(`refusing: ${COPY} is not the scratch copy`);
const NODE = "node:v1:257b06976be8cdd9e1d89aaaa116eda38b00ce3f149c280b50a806c2099e7865";
const REPO = "file:///D:/projexts/moe-next/";

const raw = new DatabaseSync(COPY, { readOnly: true });
const { projectId } = raw.prepare(
  "SELECT project_id AS projectId FROM store_project_binding WHERE singleton = 1").get();
raw.close();

const { SqliteEventStore } = await import(`${REPO}packages/store/src/index.ts`);
const fixed = await import(`${REPO}apps/daemon/src/review/governance-decision-ledger.js`);
const { decideGovernanceEscalation } =
  await import(`${REPO}apps/daemon/src/review/governance-escalation-decider.js`);
const { readReviewLedger } = await import(`${REPO}apps/daemon/src/review/review-read-model.js`);
const prefix = await import(pathToFileURL(`${SCRATCH}/ledger-prefix.mts`).href);

const store = SqliteEventStore.openForProject(COPY, projectId);
const aggregateId = fixed.governanceAggregateId(projectId);
console.log("projectId", projectId, "aggregate", aggregateId);
for (const event of store.readEvents(aggregateId)) {
  if (event.eventType !== "GovernanceDecisionRecorded") continue;
  const row = JSON.parse(new TextDecoder().decode(event.payload));
  console.log("row", String(event.globalPosition), event.committedAt, `${Object.keys(row).length} keys`,
    "findingSubject" in row ? "findingSubject=" + row.findingSubject : "NO findingSubject",
    row.subjectRef === NODE ? "node=257b0697" : row.subjectRef, "reviewVersion", row.reviewVersion);
}
const review = readReviewLedger(store, projectId, NODE);
console.log("review ledger:", JSON.stringify({ accepted: review.accepted !== undefined,
  replanned: review.replanned, rounds: review.rounds.length, unreadable: review.unreadable,
  version: review.version, latestRoute: review.rounds.at(-1)?.routing.route }));
console.log("PRE-FIX (HEAD blob) fundedOn:", prefix.createGovernanceDecisionLedger(store, projectId).fundedOn(NODE));
console.log("FIXED fundedOn:", fixed.createGovernanceDecisionLedger(store, projectId).fundedOn(NODE));
console.log("FIXED all():", fixed.createGovernanceDecisionLedger(store, projectId).all()
  ?.map((r) => `${r.reviewVersion}/${r.findingSubject}`).join(" | "));
for (const maxDecisions of [1, 10]) {
  let asked = 0;
  const outcome = await decideGovernanceEscalation({
    advisor: () => { asked += 1; return Promise.resolve(null); },
    clock: () => new Date().toISOString(),
    policy: { kind: "AI_GOVERNOR", maxDecisions },
    projectId, store,
  }, NODE);
  console.log(`FIXED decide (maxDecisions ${maxDecisions}):`, JSON.stringify(outcome), "advisor asked:", asked);
}
store.close();
```
SqliteEventStore has no read-only open (packages/store/src/sqlite-event-store.ts:106-140: open/openForProject are read-write), and the production ledger + decider need one, so only the raw projectId read used DatabaseSync {readOnly:true}; the store handle was opened read-write on the disposable COPY. Nothing ever opened the live path.
